#!/usr/bin/env bash
# Store the alerting credentials for one environment in Secrets Manager (INF-16).
#
# Run once per environment by a team member, from a laptop. The values are typed at the prompt, so they
# never reach Git, GitHub or the shell history. The secret is deliberately NOT a Terraform resource:
# staging is destroyed every evening, and a Telegram bot token can't be regenerated by code, so the
# secret has to outlive the environment. External Secrets copies it into the monitoring namespace
# (deploy/helm/observability/templates/externalsecrets.yaml).
#
#   deploy/bootstrap/put-alert-secret.sh staging
set -euo pipefail

ENV="${1:?usage: put-alert-secret.sh <staging|prod>}"
case "$ENV" in staging | prod) ;; *) echo "unknown env: $ENV" >&2; exit 1 ;; esac

REGION="us-east-1"
NAME="g4-merlion-$ENV/monitoring/alerting"

read -rsp "Telegram bot token: " TELEGRAM_BOT_TOKEN; echo
read -rsp "SMTP app password (Enter to skip email): " SMTP_PASSWORD; echo
GRAFANA_ADMIN_PASSWORD="$(openssl rand -base64 24 | tr -d '/+=')"

VALUE="$(jq -n \
  --arg t "$TELEGRAM_BOT_TOKEN" --arg s "${SMTP_PASSWORD:-unused}" --arg g "$GRAFANA_ADMIN_PASSWORD" \
  '{telegram_bot_token: $t, smtp_password: $s, grafana_admin_user: "admin", grafana_admin_password: $g}')"

if aws secretsmanager describe-secret --region "$REGION" --secret-id "$NAME" >/dev/null 2>&1; then
  aws secretsmanager put-secret-value --region "$REGION" --secret-id "$NAME" --secret-string "$VALUE" >/dev/null
  echo "Updated $NAME"
else
  # AWS-managed key (aws/secretsmanager): the env's own key is destroyed with staging every evening.
  # Tags: Project keeps the training account's nightly cleanup away; Environment keeps the other
  # env's roles out (env fence).
  aws secretsmanager create-secret --region "$REGION" --name "$NAME" \
    --description "Alertmanager and Grafana credentials for $ENV (set by put-alert-secret.sh)" \
    --secret-string "$VALUE" \
    --tags Key=Project,Value=capstone-project-group-04 Key=Team,Value=g4 \
           Key=Environment,Value="$ENV" Key=ManagedBy,Value=script Key=Stack,Value=monitoring >/dev/null
  echo "Created $NAME"
fi
echo "Grafana admin password: read it with"
echo "  aws secretsmanager get-secret-value --region $REGION --secret-id $NAME --query SecretString --output text | jq -r .grafana_admin_password"
